function InvoiceList() {
  const [invoices, setInvoices] = useState(null);
  useEffect(() => { fetchInvoices().then(setInvoices); }, []);
  if (!invoices) return <p>Loading...</p>;
  return (
    <div>
      {invoices.map(inv => (
        <div key={inv.id}>
          <img src={inv.logoUrl} />
          <span>{inv.customer}</span>
          <span>{inv.amount}</span>
        </div>
      ))}
    </div>
  );
}
